class RC_Config(SchemaObject):
    card = SchemaField(name="card")
    slot = SchemaField(name="slot")
    chassis = SchemaField(name="chassis")
    context = SchemaField(name="context")
    load = SchemaField(name="load")
    rf = SchemaField(name="rf")
    dl = SchemaField(name="dl")
    ul = SchemaField(name="ul")
    clk_ref_in = SchemaField(name="clk_ref_in", optional=True, checks=[SchemaObject.is_boolean])
    clk_ref_out = SchemaField(name="clk_ref_out", optional=True, checks=[SchemaObject.is_boolean])
    interface_mode = SchemaField(name="interface_mode", optional=True,
                                 checks=[SchemaObject.check_interface_mode])
    frequency_range = SchemaField(name="frequency_range", optional=True, checks=[SchemaObject.check_frequency_range])
    subcarrier_spacing = SchemaField(name="subcarrier_spacing", optional=True,
                                     checks=[SchemaObject.check_subcarrier_spacing])
    test_mode = SchemaField(name="test_mode", optional=True, checks=[SchemaObject.check_mode])

    def __init__(self, **kwargs):
        self.__dict__.update(**kwargs)
        super(RC_Config, self).__init__()


